// drawing(): an object or a scene as SVG, once or as several takes. Takes are the same composition drawn with another
// pen each (line boil and settling); CSS cycles them, so a server-rendered page boils without a script. Only the
// first take is named for screen readers; the others are decorative copies.
import { getObject, tile } from "./library"
import { SCENES, type SceneName } from "./scenes"
import type { HandName } from "./stroke"

export interface DrawingOptions {
  /** An object id from the library, such as "turntable". */
  object?: string
  /** A scene: "room", "studio" or "bistro". */
  scene?: SceneName
  /** Same seed, same drawing, on the server, in the browser and in every build. */
  seed: string | number
  hand?: HandName
  /** 1 for a still drawing; 3 for line boil and settling. */
  takes?: number
  /** The accessible name. Defaults to the object's or scene's own; pass "" for a decorative drawing. */
  title?: string
}

/** The drawing's takes, each a complete SVG string. */
export function drawing({
  object,
  scene,
  seed,
  hand = "lively",
  takes = 1,
  title,
}: DrawingOptions): string[] {
  const key = String(seed)
  const out: string[] = []
  for (let take = 0; take < Math.max(1, takes); take++) {
    const named = take === 0 ? title : ""
    if (scene) {
      const sc = SCENES[scene]
      const label = named ?? sc.label
      out.push(
        sc
          .compose(key, hand, take)
          .svg(sc.size[0], sc.size[1], label || undefined),
      )
    } else {
      const o = object ? getObject(object) : undefined
      if (!o)
        throw new Error(
          `drawing() needs a known object or scene, got "${object ?? scene}"`,
        )
      const label = named ?? o.name
      out.push(tile(o, key, hand, take, label || undefined))
    }
  }
  return out
}

// Points and the arithmetic every drawing shares. Lengths use Math.sqrt, which every engine rounds the same way;
// Math.hypot and ** do not, and a last-bit difference in a length can change how many points a stroke gets.

export type Point = [number, number]

export const deg = Math.PI / 180

/** Round to hundredths, so last-bit noise from a maths function cannot reach a count or a random draw. */
export const snap = (n: number) => Math.round(n * 100) / 100

export const add = (a: Point, b: Point, f = 1): Point => [
  a[0] + b[0] * f,
  a[1] + b[1] * f,
]
export const lerp = (a: Point, b: Point, t: number): Point => [
  a[0] + (b[0] - a[0]) * t,
  a[1] + (b[1] - a[1]) * t,
]
export const times = (v: Point, f: number): Point => [v[0] * f, v[1] * f]
export const length = (v: Point) => Math.sqrt(v[0] * v[0] + v[1] * v[1])
export const dist = (a: Point, b: Point) => length([b[0] - a[0], b[1] - a[1]])

/** Centre and axes for a circle of radius r, as the pen's ring and disc take them. */
export const dot = (c: Point, r: number): [Point, Point, Point] => [
  c,
  [r, 0],
  [0, r],
]

/** Points on an ellipse from a0 to a1 degrees: 0 is right, 90 is down. */
export function arc(
  c: Point,
  rx: number,
  ry: number,
  a0: number,
  a1: number,
  n = 16,
): Point[] {
  return Array.from({ length: n + 1 }, (_, i) => {
    const a = (a0 + ((a1 - a0) * i) / n) * deg
    return [c[0] + rx * Math.cos(a), c[1] + ry * Math.sin(a)]
  })
}

/** A rectangle's corners from its top-left corner, clockwise. */
export const rect = (x: number, y: number, w: number, h: number): Point[] => [
  [x, y],
  [x + w, y],
  [x + w, y + h],
  [x, y + h],
]

/** Turn a point round a centre by a degrees. */
export function turn(pt: Point, c: Point, a: number): Point {
  const [s, k] = [Math.sin(a * deg), Math.cos(a * deg)]
  const [dx, dy] = [pt[0] - c[0], pt[1] - c[1]]
  return [c[0] + dx * k - dy * s, c[1] + dx * s + dy * k]
}

/** The last item of a list that is known not to be empty. */
export const last = <T>(items: readonly T[]): T => items[items.length - 1] as T

// A drawing in layers of paths. `blank` hides everything drawn before it inside a shape (a mask, so the paper's
// texture still shows), which is how a figure stands in front of a wall line. Paths drawn between two blanks form one
// layer, masked once by every blank that came after it: one mask per layer, never nested, which keeps paint cheap.

export interface Sheet {
  /** A pen line. */
  stroke(d: string): void
  /** A pocket of solid ink. */
  fill(d: string): void
  /** The pen's wash: art fills only. */
  wash(d: string): void
  /** Flat paper, for small holes such as a record's label. */
  paper(d: string): void
  /** Markup the helpers cannot express, such as an even-odd ring. */
  raw(markup: string): void
  /** Hide everything drawn so far inside this shape. */
  blank(d: string): void
  /** The SVG: named by `label` (role="img"), or decorative without one. */
  svg(width: number, height: number, label?: string): string
}

const escape = (text: string) =>
  text.replace(
    /[&<>"]/g,
    (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c] ?? c,
  )

/** `id` prefixes the sheet's mask ids; derive it from the drawing's seed and take so server and browser agree. */
export function sheet(id: string): Sheet {
  const layers: string[][] = [[]]
  const blanks: string[] = []
  const top = () => layers[layers.length - 1] as string[]
  const add = (cls: string) => (d: string) => {
    top().push(`<path class="${cls}" d="${d}"/>`)
  }
  return {
    stroke: add("ln"),
    fill: add("ink"),
    wash: add("wash"),
    paper: add("sheet-fill"),
    raw: (markup) => {
      top().push(markup)
    },
    blank(d) {
      if (layers.every((l) => !l.length)) return
      blanks.push(d)
      layers.push([])
    },
    svg(width, height, label) {
      const name = label
        ? `role="img" aria-label="${escape(label)}"`
        : `aria-hidden="true"`
      const pad = 24
      const box = `x="${-pad}" y="${-pad}" width="${width + 2 * pad}" height="${height + 2 * pad}"`
      let defs = ""
      let body = ""
      layers.forEach((paths, i) => {
        if (!paths.length) return
        const after = blanks.slice(i)
        if (!after.length) {
          body += paths.join("")
          return
        }
        const holes = after.map((d) => `<path d="${d}"/>`).join("")
        defs += `<mask id="${id}-m${i}" maskUnits="userSpaceOnUse" ${box}><rect ${box} fill="#fff"/><g fill="#000">${holes}</g></mask>`
        body += `<g mask="url(#${id}-m${i})">${paths.join("")}</g>`
      })
      // fl-size-own contains "size-", so shadcn's icon rule ([&_svg:not([class*='size-'])]:size-4) leaves a drawing
      // or pen mark inside a button or menu item at the size its call site gives it.
      return `<svg class="fl-drawing fl-size-own" viewBox="0 0 ${width} ${height}" ${name}>${defs ? `<defs>${defs}</defs>` : ""}${body}</svg>`
    },
  }
}

// Lettering: words drawn by the pen from the skeleton alphabet, in four faces. Each letter takes a small seeded tilt
// and lift, so the same word reads as hand-lettered and is the same on every render. Ported from the prototype in
// specimen/lettering/lettering.js; lengths go through snap() before they decide a count.
import { dist, last, snap, type Point } from "./geometry"
import { GLYPHS, type Glyph } from "./glyphs"
import { sheet, type Sheet } from "./layers"
import { seedOf, stream } from "./seed"
import { pen, type HandName, type Pen } from "./stroke"

interface Face {
  name: string
  /** Horizontal scale of the skeleton. */
  sx: number
  /** Space after each letter. */
  track: number
  /** Serif length at free stroke ends. */
  serif?: number
  /** Half the width of a ribbon stroke. */
  ribbon?: number
  /** Spacing of a tramline's three lines. */
  lines?: number
}

export const FACES = {
  liner: { name: "Liner", sx: 1, track: 24, serif: 12 },
  stilt: { name: "Stilt", sx: 0.54, track: 15, serif: 9 },
  ribbon: { name: "Ribbon", sx: 1.04, track: 26, ribbon: 5.5 },
  tramline: { name: "Tramline", sx: 1, track: 28, lines: 4.6 },
} satisfies Record<string, Face>

export type FaceName = keyof typeof FACES

/** Marks that never take serifs. */
const PLAIN = new Set(["-", "–", "/", "+", "'", ",", "&"])

const closed = (st: Point[]) =>
  st.length > 2 && dist(st[0] as Point, last(st)) < 0.5

/** Points every `step` units along a stroke. */
function resample(st: Point[], step = 2.5): Point[] {
  const out: Point[] = [st[0] as Point]
  for (let i = 1; i < st.length; i++) {
    const [a, b] = [st[i - 1] as Point, st[i] as Point]
    const n = Math.max(1, Math.round(snap(dist(a, b)) / step))
    for (let j = 1; j <= n; j++)
      out.push([a[0] + ((b[0] - a[0]) * j) / n, a[1] + ((b[1] - a[1]) * j) / n])
  }
  return out
}

/** The stroke moved sideways by d along its normals (a ring stays a ring). */
function offset(st: Point[], d: number): Point[] {
  const pts = resample(st)
  const ring = closed(st)
  return pts.map((pt, i): Point => {
    const a = pts[i > 0 ? i - 1 : ring ? pts.length - 2 : 0] as Point
    const b = pts[
      i < pts.length - 1 ? i + 1 : ring ? 1 : pts.length - 1
    ] as Point
    const len = dist(a, b) || 1
    return [
      pt[0] - ((b[1] - a[1]) / len) * d,
      pt[1] + ((b[0] - a[0]) / len) * d,
    ]
  })
}

/** Is this end of a stroke free, or does it meet another stroke of the same letter? */
const free = (end: Point, strokes: Point[][], self: number) =>
  strokes.every(
    (st, i) => i === self || resample(st, 2).every((pt) => dist(pt, end) > 4),
  )

/** A short tick across a stroke's free end: the serif. */
function serif(end: Point, toward: Point, len: number): [Point, Point] {
  const d = dist(end, toward) || 1
  const [nx, ny] = [-(toward[1] - end[1]) / d, (toward[0] - end[0]) / d]
  return [
    [end[0] - (nx * len) / 2, end[1] - (ny * len) / 2],
    [end[0] + (nx * len) / 2, end[1] + (ny * len) / 2],
  ]
}

function strokeLetter(
  s: Sheet,
  p: Pen,
  face: Face,
  strokes: Point[][],
  plain = false,
) {
  strokes.forEach((st, i) => {
    if (face.ribbon) {
      const [L, R] = [offset(st, face.ribbon), offset(st, -face.ribbon)]
      if (closed(st)) {
        s.raw(
          `<path class="wash" fill-rule="evenodd" d="${p.shape(L)}${p.shape(R)}"/>`,
        )
      } else {
        s.wash(p.shape([...L, ...R.slice().reverse()]))
        s.stroke(p.line(L[0] as Point, R[0] as Point))
        s.stroke(p.line(last(L), last(R)))
      }
      s.stroke(p.path(L))
      s.stroke(p.path(R))
    } else if (face.lines) {
      for (const d of [-face.lines, 0, face.lines])
        s.stroke(p.path(offset(st, d)))
    } else {
      s.stroke(p.path(st))
      if (!face.serif || plain || closed(st)) return
      const ends: [Point, Point][] = [
        [st[0] as Point, st[1] as Point],
        [last(st), st[st.length - 2] as Point],
      ]
      for (const [end, toward] of ends)
        if (free(end, strokes, i))
          s.stroke(p.line(...serif(end, toward, face.serif)))
    }
  })
}

export interface LetteringOptions {
  face?: FaceName
  /** Defaults to the text, so a word always looks the same. */
  seed?: string | number
  hand?: HandName
  /** 1 for still lettering; 3 for line boil and settling. */
  takes?: number
}

/**
 * Draw a word or a line in one face, as one SVG per take, named by the text (only the first take is named). Letters
 * the alphabet lacks draw as a question mark.
 */
export function lettering(
  text: string,
  {
    face: faceName = "liner",
    seed = text,
    hand = "lively",
    takes = 1,
  }: LetteringOptions = {},
): string[] {
  const face: Face = FACES[faceName]
  const key = `${seed}:${faceName}`
  const out: string[] = []
  for (let take = 0; take < Math.max(1, takes); take++) {
    const s = sheet(`fl${seedOf(key).toString(36)}l${take}`)
    const p = pen(key, hand, take)
    const r = stream(seedOf(key), "letters")
    let x = 14
    for (const ch of text.toUpperCase()) {
      const g: Glyph = GLYPHS[ch] ?? (GLYPHS["?"] as Glyph)
      const w = g.w * face.sx
      const tilt = (r.signed() * 2.2 * Math.PI) / 180
      const lift = r.signed() * 2
      const c: Point = [x + w / 2, 50]
      const at = ([u, v]: Point): Point => {
        const [dx, dy] = [x + u * face.sx - c[0], v + 22 + lift - c[1]]
        return [
          c[0] + dx * Math.cos(tilt) - dy * Math.sin(tilt),
          c[1] + dx * Math.sin(tilt) + dy * Math.cos(tilt),
        ]
      }
      strokeLetter(
        s,
        p,
        face,
        g.s.map((st) => st.map(at)),
        PLAIN.has(ch),
      )
      strokeLetter(
        s,
        p,
        face,
        (g.m ?? []).map((st) => st.map(at)),
        true,
      )
      for (const d of g.d ?? []) s.fill(p.disc(at(d), [3.2, 0], [0, 3.2]))
      x += w + face.track
    }
    out.push(
      s.svg(
        Math.round(x - face.track + 14),
        144,
        take === 0 ? text : undefined,
      ),
    )
  }
  return out
}

// The object library's registry. Each object is one draw function filed in a collection, so drawing(), scenes and
// the docs find objects the same way. The library is meant to keep growing; defining an object is all it takes.
import type { Point } from "./geometry"
import { seedOf, stream, type Stream } from "./seed"
import { sheet, type Sheet } from "./layers"
import { pen, type HandName, type Pen } from "./stroke"

export const COLLECTIONS = [
  ["indie", "Indie"],
  ["food", "Food & drink"],
  ["studio", "Studio"],
  ["people", "People"],
] as const

export type Collection = (typeof COLLECTIONS)[number][0]

/** Choices an object may take instead of drawing them from its seed. */
export interface DrawOptions {
  kind?: string
  pose?: string
  view?: string
  dish?: string
  hair?: string
  glasses?: boolean
  beard?: boolean
  black?: boolean
  wine?: boolean
  /** Where a hanging object's cord starts. */
  top?: number
  w?: number
  h?: number
  d?: number
  legs?: number
}

/** Draw one object into a sheet at `at`, scaled by `k`. What it returns (a box top, say) lets scenes stack things. */
export type Draw = (
  s: Sheet,
  p: Pen,
  r: Stream,
  at: Point,
  k: number,
  options: DrawOptions,
) => unknown

export interface DrawingObject {
  id: string
  name: string
  collection: Collection
  /** The object's own tile, and where and how large it draws there. */
  size: [number, number]
  at: Point
  k: number
  tags: string[]
  draw: Draw
}

/**
 * A collection's object maker, so each collection file writes one line per object:
 * `const T = objectsIn("studio")`, then `define(T("desk", "Desk", [290, 150], [12, 140], 1, desk, ["work"]))`.
 */
export const objectsIn =
  (collection: Collection) =>
  (
    id: string,
    name: string,
    size: [number, number],
    at: Point,
    k: number,
    draw: Draw,
    tags: string[],
  ): DrawingObject => ({ id, name, collection, size, at, k, draw, tags })

const all: DrawingObject[] = []

export function define(...objects: DrawingObject[]) {
  for (const o of objects) if (!all.some((x) => x.id === o.id)) all.push(o)
}

export const getObject = (id: string) => all.find((o) => o.id === id)
export const listObjects = (collection?: Collection) =>
  all.filter((o) => !collection || o.collection === collection)

/**
 * Draw an object into an existing sheet with its own fork of the seed. The composition comes from the `shape`
 * stream and never changes between takes; only the pen does.
 */
export function place(
  s: Sheet,
  id: string,
  seed: string,
  hand: HandName,
  at: Point,
  k = 1,
  options: DrawOptions = {},
  take = 0,
): unknown {
  const o = getObject(id)
  if (!o) throw new Error(`No drawing object "${id}"`)
  const key = `${seed}:${id}`
  return o.draw(
    s,
    pen(key, hand, take),
    stream(seedOf(key), "shape"),
    at,
    k,
    options,
  )
}

/** One object alone on its tile, as an SVG string. */
export function tile(
  o: DrawingObject,
  seed: string,
  hand: HandName,
  take = 0,
  label: string | undefined = o.name,
) {
  const s = sheet(`fl${seedOf(`${seed}:${o.id}`).toString(36)}t${take}`)
  place(s, o.id, seed, hand, o.at, o.k, {}, take)
  return s.svg(o.size[0], o.size[1], label)
}

// Studio: the freelancer's screens, and what is on them (a website, code, a design canvas or an app). `at` is
// bottom-left unless a function says otherwise. Composition comes from `r` (the shape stream), never from the pen,
// so takes agree.
import { add, lerp, rect, turn, type Point } from "../geometry"
import { define, type Draw, objectsIn } from "../library"
import { box, depth } from "../shapes"
import type { Sheet } from "../layers"
import type { Stream } from "../seed"
import type { Pen } from "../stroke"

/** Map u, v in [0, 1] onto a four-sided screen given top-left, top-right, bottom-right, bottom-left. */
function quad(corners: Point[]) {
  const [A, B, C, D] = corners as [Point, Point, Point, Point]
  return (u: number, v: number) => lerp(lerp(A, B, u), lerp(D, C, u), v)
}

/** What a screen shows: "site", "code", "canvas" or "app"; the first three are drawn from the seed. */
export function screen(
  s: Sheet,
  p: Pen,
  r: Stream,
  corners: Point[],
  kind: string = r.pick(["site", "code", "canvas"]),
) {
  const q = quad(corners)
  const box4 = (u0: number, v0: number, u1: number, v1: number) => [
    q(u0, v0),
    q(u1, v0),
    q(u1, v1),
    q(u0, v1),
  ]
  if (kind === "site") {
    s.stroke(p.line(q(0, 0.16), q(1, 0.16)))
    s.fill(p.disc(q(0.08, 0.08), [2, 0], [0, 2]))
    for (let i = 0; i < 3; i++)
      s.stroke(p.line(q(0.6 + i * 0.12, 0.08), q(0.68 + i * 0.12, 0.08)))
    s.stroke(p.edges(box4(0.08, 0.24, 0.92, 0.6)))
    s.stroke(
      p.path([
        q(0.12, 0.56),
        q(0.32, 0.36),
        q(0.46, 0.5),
        q(0.58, 0.42),
        q(0.88, 0.56),
      ]),
    )
    s.stroke(p.ring(q(0.76, 0.33), [3, 0], [0, 3]))
    s.stroke(p.line(q(0.08, 0.69), q(0.6, 0.69)))
    s.stroke(p.line(q(0.08, 0.77), q(0.82, 0.77)))
    s.fill(p.shape(box4(0.08, 0.85, 0.3, 0.94)))
  } else if (kind === "code") {
    let indent = 0
    for (let v = 0.12; v < 0.92; v += 0.1) {
      indent = Math.max(0, Math.min(3, indent + Math.round(r.signed() * 1.2)))
      const u0 = 0.14 + indent * 0.08
      s.stroke(p.line(q(0.05, v), q(0.08, v)))
      s.stroke(
        p.line(q(u0, v), q(Math.min(0.94, u0 + r.between(0.15, 0.55)), v)),
      )
    }
  } else if (kind === "canvas") {
    s.stroke(p.line(q(0.2, 0), q(0.2, 1)))
    s.stroke(p.line(q(0.8, 0), q(0.8, 1)))
    for (let v = 0.12; v < 0.6; v += 0.12)
      s.stroke(p.line(q(0.04, v), q(0.15, v)))
    s.stroke(p.edges(box4(0.3, 0.18, 0.7, 0.82)))
    s.stroke(p.ring(q(0.43, 0.42), [7, 0], [0, 7]))
    s.fill(p.shape(box4(0.5, 0.5, 0.62, 0.7)))
    for (let v = 0.14; v < 0.5; v += 0.1)
      s.stroke(p.line(q(0.84, v), q(0.96, v)))
  } else {
    s.stroke(p.line(q(0.1, 0.1), q(0.6, 0.1)))
    for (const v of [0.2, 0.46]) {
      s.stroke(p.edges(box4(0.1, v, 0.9, v + 0.2)))
      s.stroke(p.line(q(0.18, v + 0.07), q(0.7, v + 0.07)))
      s.stroke(p.line(q(0.18, v + 0.13), q(0.5, v + 0.13)))
    }
    for (let i = 0; i < 4; i++)
      s.fill(p.disc(q(0.2 + i * 0.2, 0.88), [1.5, 0], [0, 1.5]))
  }
}

export const laptop: Draw = (s, p, r, at, k = 1, { kind } = {}) => {
  const o = depth(r)
  const [x, y] = at
  const [w, d, h] = [124 * k, 64 * k, 80 * k]
  const back = (u: number) => add([x + w * u, y - 4 * k], o, d)
  const lean: Point = [o[0] * 8 * k, -h]
  const lid: [Point, Point, Point, Point] = [
    add(back(0), lean),
    add(back(1), lean),
    back(1),
    back(0),
  ]
  s.blank(p.shape(lid))
  s.stroke(p.edges(lid))
  const inset = (pt: Point, u: number, v: number) => add(pt, [u * k, v * k])
  screen(
    s,
    p,
    r,
    [
      inset(lid[0], 6, 6),
      inset(lid[1], -6, 6),
      inset(lid[2], -6, -6),
      inset(lid[3], 6, -6),
    ],
    kind,
  )
  const deck = box(s, p, o, at, w, 4 * k, d)
  const keys = (u0: number, v0: number, u1: number, v1: number) => [
    deck.top(u0, v0),
    deck.top(u1, v0),
    deck.top(u1, v1),
    deck.top(u0, v1),
  ]
  s.stroke(p.edges(keys(0.08, 0.38, 0.92, 0.9)))
  for (const v of [0.55, 0.72])
    s.stroke(p.line(deck.top(0.08, v), deck.top(0.92, v)))
  s.stroke(p.edges(keys(0.38, 0.08, 0.62, 0.3)))
}

/** A monitor on its stand; `at` is the centre of the stand's foot. */
export const monitor: Draw = (s, p, r, at, k = 1, { kind } = {}) => {
  const [x, y] = at
  const [w, h] = [150 * k, 96 * k]
  const top = y - 30 * k - h
  s.stroke(p.ring([x, y - 3 * k], [26 * k, 0], [0, 5 * k]))
  s.stroke(p.line([x - 4 * k, y - 4 * k], [x - 4 * k, y - 30 * k]))
  s.stroke(p.line([x + 4 * k, y - 4 * k], [x + 4 * k, y - 30 * k]))
  const outer = rect(x - w / 2, top, w, h)
  s.blank(p.shape(outer))
  s.stroke(p.edges(outer))
  const inner = rect(x - w / 2 + 6 * k, top + 6 * k, w - 12 * k, h - 14 * k)
  s.stroke(p.edges(inner))
  const pad: Point[] = [
    [4, 4],
    [-4, 4],
    [-4, -4],
    [4, -4],
  ]
  screen(
    s,
    p,
    r,
    inner.map((pt, i) => add(pt, pad[i] as Point, k)),
    kind,
  )
}

export const phone: Draw = (s, p, r, at, k = 1) => {
  const [x, y] = at
  const P = (u: number, v: number): Point => [x + u * k, y - v * k]
  const body = [
    P(4, 0),
    P(38, 0),
    P(42, 4),
    P(42, 82),
    P(38, 86),
    P(4, 86),
    P(0, 82),
    P(0, 4),
  ]
  s.blank(p.shape(body))
  s.stroke(p.edges(body))
  s.fill(p.shape([P(16, 80), P(26, 80), P(26, 77.5), P(16, 77.5)]))
  screen(s, p, r, [P(5, 72), P(37, 72), P(37, 8), P(5, 8)], "app")
}

/** A browser window showing a website, with the pointer on it. */
export const website: Draw = (s, p, r, at, k = 1) => {
  const [x, y] = at
  const [w, h] = [172 * k, 124 * k]
  const win = rect(x, y - h, w, h)
  s.blank(p.shape(win))
  s.stroke(p.edges(win))
  s.stroke(p.line([x, y - h + 16 * k], [x + w, y - h + 16 * k]))
  for (let i = 0; i < 3; i++)
    s.stroke(
      p.ring([x + (10 + i * 9) * k, y - h + 8 * k], [2.6 * k, 0], [0, 2.6 * k]),
    )
  s.stroke(p.edges(rect(x + 44 * k, y - h + 4 * k, 96 * k, 8 * k)))
  screen(
    s,
    p,
    r,
    [
      [x + 6 * k, y - h + 22 * k],
      [x + w - 6 * k, y - h + 22 * k],
      [x + w - 6 * k, y - 6 * k],
      [x + 6 * k, y - 6 * k],
    ],
    "site",
  )
  const tip: Point = [x + w * 0.27, y - h * 0.08]
  const arrow = [
    tip,
    add(tip, [0, 16 * k]),
    add(tip, [4 * k, 12 * k]),
    add(tip, [8 * k, 19 * k]),
    add(tip, [10.5 * k, 18 * k]),
    add(tip, [7 * k, 11 * k]),
    add(tip, [12 * k, 11 * k]),
  ]
  s.blank(p.shape(arrow))
  s.fill(p.shape(arrow.map((pt) => turn(pt, tip, -8))))
}

