// The small marks the interface draws with the pen: a tick that overshoots its box, a ring round a word, a dot, an
// underline, a strike, an arrow for a hand note, a chevron, a switch's pill and a border at a fixed size. Each is a
// fixed viewBox; marks that hug content (ring, underline, strike) stretch to their box with non-scaling strokes.
import type { Point } from "./geometry"
import { sheet, type Sheet } from "./layers"
import { seedOf } from "./seed"
import { pen, type HandName, type Pen } from "./stroke"

interface MarkSpec {
  size: [number, number]
  /** Stretch to the element's box (preserveAspectRatio="none") instead of keeping the drawing's proportions. */
  stretch?: boolean
  draw(s: Sheet, p: Pen): void
}

const wave = (y: number, amp: number, phase: number) =>
  Array.from({ length: 6 }, (_, i): Point => [
    2 + i * 19.2,
    y + Math.sin(i * 0.9 + phase) * amp,
  ])

export const MARKS = {
  tick: {
    size: [24, 24],
    draw: (s, p) =>
      s.stroke(
        p.path([
          [4, 12],
          [10, 19.5],
          [25, -3],
        ]),
      ),
  },
  ring: {
    size: [100, 40],
    stretch: true,
    draw: (s, p) => s.stroke(p.ring([50, 20], [48, 0], [0, 18])),
  },
  dot: {
    size: [20, 20],
    draw: (s, p) => s.fill(p.disc([10, 10], [4.2, 0], [0, 4.2])),
  },
  underline: {
    size: [100, 10],
    stretch: true,
    draw: (s, p) => s.stroke(p.path(wave(5, 1.2, 0))),
  },
  strike: {
    size: [100, 10],
    stretch: true,
    draw: (s, p) => s.stroke(p.path(wave(5, 0.8, 1.7))),
  },
  arrow: {
    size: [76, 50],
    draw(s, p) {
      s.stroke(
        p.path([
          [4, 6],
          [22, 4],
          [44, 12],
          [60, 28],
          [66, 42],
        ]),
      )
      s.stroke(
        p.path([
          [57, 36],
          [66, 43],
          [70, 32],
        ]),
      )
    },
  },
  /** A short straight arrow to the inline end: next, forward, jump to latest. */
  next: {
    size: [26, 16],
    draw(s, p) {
      s.stroke(p.line([2, 8], [23, 8]))
      s.stroke(
        p.path([
          [16.5, 2.5],
          [23.5, 8],
          [16.5, 13.5],
        ]),
      )
    },
  },
  chevron: {
    size: [14, 10],
    draw: (s, p) =>
      s.stroke(
        p.path([
          [2, 2],
          [7, 7.5],
          [12, 2],
        ]),
      ),
  },
  pill: {
    size: [44, 24],
    draw(s, p) {
      const r = 11
      const right = p.round([32, 12], [r, 0], [0, r], -Math.PI / 2, Math.PI)
      const left = p.round([12, 12], [r, 0], [0, r], Math.PI / 2, Math.PI)
      s.stroke(p.path([...right, ...left, right[0] as Point]))
    },
  },
} satisfies Record<string, MarkSpec>

export type MarkName = keyof typeof MARKS

/** One mark as SVG. Decorative: the element it marks carries the meaning. */
export function penMark(
  name: MarkName,
  seed: string | number,
  hand: HandName = "lively",
  take = 0,
) {
  const spec: MarkSpec = MARKS[name]
  const key = `${seed}:${name}`
  const s = sheet(`fl${seedOf(key).toString(36)}k${take}`)
  spec.draw(s, pen(key, hand, take))
  const svg = s.svg(spec.size[0], spec.size[1])
  return spec.stretch
    ? svg.replace("<svg ", '<svg preserveAspectRatio="none" ')
    : svg
}

/** A border drawn edge by edge at a known size, so its corners cross like the reference label's. */
export function penBorder(
  seed: string | number,
  width: number,
  height: number,
  hand: HandName = "lively",
) {
  const key = `${seed}:border`
  const s = sheet(`fl${seedOf(key).toString(36)}b`)
  s.stroke(
    pen(key, hand).edges([
      [0, 0],
      [width, 0],
      [width, height],
      [0, height],
    ]),
  )
  return s.svg(width, height)
}

// The pen through data. A chart's line must pass exactly through every data point and a bar's corners must sit
// exactly on its value, so here the wobble fades to nothing at each point and lives only on the stretch between two:
// the pen still draws the line, and the data does not move. Same cross-engine rules as the stroke engine.
import { dist, snap, type Point } from "./geometry"
import { fork, prng, seedOf } from "./seed"
import { HANDS, noise, resample, type HandName } from "./stroke"

const r1 = (n: number) => Math.round(n * 10) / 10

export interface Plot {
  /**
   * One stroke through runs of points. Each run goes from one data point to the next (a straight pair, or a curve
   * sampled densely); the stroke wobbles inside a run and passes exactly through its ends.
   */
  through(runs: Point[][]): Point[]
  /** The same, as SVG path data. */
  path(runs: Point[][]): string
  /** A polygon edge by edge: every corner exact, each edge running a little past its corners (or short of them). */
  edges(corners: Point[], closed?: boolean): string
}

/** A pen for data, seeded from the series and its values (never from layout), so a chart draws the same each time. */
export function plot(seed: string | number, handName: HandName = "calm"): Plot {
  const hand = HANDS[handName] ?? HANDS.calm
  const rand = prng(fork(seedOf(seed), "plot"))

  function run(points: Point[]): Point[] {
    const pts = resample(
      points.map(([x, y]) => [snap(x), snap(y)]),
      3,
    )
    const size = pts[pts.length - 1]?.[2] || 1
    const slow = noise(rand, size, hand.wave, hand.amp)
    const fine = noise(rand, size, 7, hand.tremor)
    return pts.map(([x, y, s], i): Point => {
      if (i === 0 || i === pts.length - 1) return [x, y]
      const a = pts[i - 1] as [number, number, number]
      const b = pts[i + 1] as [number, number, number]
      const len = dist([a[0], a[1]], [b[0], b[1]]) || 1
      // Zero at both data points, full in the middle of the stretch.
      const off = (slow(s) + fine(s)) * Math.sin((Math.PI * s) / size)
      return [x - ((b[1] - a[1]) / len) * off, y + ((b[0] - a[0]) / len) * off]
    })
  }

  const toPath = (points: Point[]) =>
    points.map(([x, y], i) => `${i ? "L" : "M"}${r1(x)} ${r1(y)}`).join("")

  function through(runs: Point[][]): Point[] {
    const out: Point[] = []
    for (const points of runs) {
      if (points.length < 2) continue
      const drawn = run(points)
      out.push(...(out.length ? drawn.slice(1) : drawn))
    }
    return out
  }

  return {
    through,
    path: (runs) => toPath(through(runs)),
    edges(corners, closed = true) {
      const ring = closed ? [...corners, corners[0] as Point] : corners
      let d = ""
      for (let i = 1; i < ring.length; i++) {
        const a = ring[i - 1] as Point
        const b = ring[i] as Point
        const len = dist(a, b) || 1
        const past = (from: Point, to: Point): Point => {
          const o = (rand() * 1.25 - 0.25) * hand.over
          return [
            from[0] + ((from[0] - to[0]) / len) * o,
            from[1] + ((from[1] - to[1]) / len) * o,
          ]
        }
        d += toPath([past(a, b), ...run([a, b]), past(b, a)])
      }
      return d
    },
  }
}

// d3's monotoneX tangents, so a drawn line and its area follow the same curve and never overshoot the data.
function slope3([x0, y0]: Point, [x1, y1]: Point, [x2, y2]: Point) {
  const h0 = x1 - x0
  const h1 = x2 - x1
  const s0 = (y1 - y0) / (h0 || (h1 < 0 ? -0 : 0))
  const s1 = (y2 - y1) / (h1 || (h0 < 0 ? -0 : 0))
  const p = (s0 * h1 + s1 * h0) / (h0 + h1)
  const sign = (v: number) => (v < 0 ? -1 : 1)
  return (
    (sign(s0) + sign(s1)) *
      Math.min(Math.abs(s0), Math.abs(s1), 0.5 * Math.abs(p)) || 0
  )
}
function slope2([x0, y0]: Point, [x1, y1]: Point, t: number) {
  const h = x1 - x0
  return h ? ((3 * (y1 - y0)) / h - t) / 2 : t
}

/** The curve from one data point to the next, as a dense run of points (a straight pair when linear). */
export function curveRuns(
  points: Point[],
  interpolation: "monotone" | "linear" = "monotone",
) {
  const n = points.length
  if (interpolation === "linear" || n < 3)
    return points.slice(1).map((to, i) => [points[i]!, to])
  const t: number[] = new Array(n).fill(0)
  for (let i = 1; i < n - 1; i++)
    t[i] = slope3(points[i - 1]!, points[i]!, points[i + 1]!)
  t[0] = slope2(points[0]!, points[1]!, t[1]!)
  t[n - 1] = slope2(points[n - 2]!, points[n - 1]!, t[n - 2]!)
  return points.slice(1).map((to, i) => {
    const from = points[i]!
    const dx = (to[0] - from[0]) / 3
    const c1: Point = [from[0] + dx, from[1] + dx * t[i]!]
    const c2: Point = [to[0] - dx, to[1] - dx * t[i + 1]!]
    const steps = Math.max(2, Math.round(snap(Math.abs(to[0] - from[0])) / 4))
    return Array.from({ length: steps + 1 }, (_, j): Point => {
      const u = j / steps
      const v = 1 - u
      const a = v * v * v
      const b = 3 * v * v * u
      const c = 3 * v * u * u
      const d = u * u * u
      return [
        a * from[0] + b * c1[0] + c * c2[0] + d * to[0],
        a * from[1] + b * c1[1] + c * c2[1] + d * to[1],
      ]
    })
  })
}

// Scenes: rooms composed from the object library, back to front, inside the hand-drawn border. Every object gets its
// own fork of the scene's seed, so two speakers in one room are drawn differently; the room's layout comes from the
// scene's `room` stream, so every take of a scene has the same composition.
import type { Point } from "./geometry"
import { place, type DrawOptions } from "./library"
import type { Box } from "./shapes"
import { seedOf, stream, type Stream } from "./seed"
import { sheet, type Sheet } from "./layers"
import { pen, type HandName, type Pen } from "./stroke"

const W = 640
const H = 440
const M = 14

interface Stage {
  s: Sheet
  p: Pen
  r: Stream
  put: (
    id: string,
    key: string,
    at: Point,
    k?: number,
    options?: DrawOptions,
  ) => unknown
  corner: number
  floor: number
  walls(): void
  rug(): void
  border(): void
}

/** What every room shares: the scene's pen and stream, a way to place objects, walls, a rug and the border. */
function stage(seed: string, hand: HandName, take: number): Stage {
  const s = sheet(`fl${seedOf(seed).toString(36)}s${take}`)
  const p = pen(seed, hand, take)
  const r = stream(seedOf(seed), "room")
  const put = (
    id: string,
    key: string,
    at: Point,
    k = 1,
    options: DrawOptions = {},
  ) => place(s, id, `${seed}:${key}`, hand, at, k, options, take)
  const corner = r.between(0.13, 0.22) * W
  const floor = r.between(0.6, 0.66) * H
  return {
    s,
    p,
    r,
    put,
    corner,
    floor,
    walls() {
      s.stroke(p.line([corner, M], [corner, floor]))
      s.stroke(p.line([corner, floor], [W - M, floor + r.signed() * 6]))
      s.stroke(p.line([corner, floor], [M, floor + (corner - M) * 0.62]))
    },
    rug() {
      const y = H - M - r.between(34, 56)
      const sway = r.next() * 3
      s.stroke(
        p.path(
          Array.from({ length: 9 }, (_, i): Point => [
            M + 40 + (i * (W - 2 * M - 80)) / 8,
            y + Math.sin((i / 8) * 4 + sway) * 14,
          ]),
        ),
      )
    },
    border: () =>
      s.stroke(
        p.edges([
          [M, M],
          [W - M, M],
          [W - M, H - M],
          [M, H - M],
        ]),
      ),
  }
}

function room(seed: string, hand: HandName, take: number) {
  const { s, p, r, put, corner, floor, walls, rug, border } = stage(
    seed,
    hand,
    take,
  )
  walls()
  if (r.chance(0.6)) {
    const [x0, x1] = [M + 12, corner - 14]
    s.stroke(
      p.edges(
        [
          [x0, floor + (corner - x0) * 0.62 + 4],
          [x0, H * 0.2],
          [x1, H * 0.12],
          [x1, floor + (corner - x1) * 0.62],
        ],
        false,
      ),
    )
    s.fill(p.disc([x1 - 7, H * 0.42], [1.8, 0], [0, 1.8]))
  }
  rug()
  put("picture", "picture", [r.between(0.62, 0.7) * W, H * 0.2], 0.875)
  put("disco-ball", "ball", [r.between(0.28, 0.36) * W, H * 0.25], 0.95, {
    top: M,
  })
  const b = put(
    "shelf",
    "shelf",
    [r.between(0.4, 0.45) * W, floor + 44],
    1.15,
  ) as Box
  put("speaker", "left", b.top(0.01, 0.22), 0.95)
  put("speaker", "right", b.top(0.83, 0.22), 0.95)
  put("turntable", "turntable", b.top(0.2, 0.08), 0.84)
  put("sunflower", "plant", [r.between(0.86, 0.89) * W, floor + 80], 1.35)
  if (r.chance(0.5))
    put("visitor", "first", [r.between(0.1, 0.13) * W, H - M - 14], 1.3, {
      pose: "walk",
    })
  if (r.chance(0.5))
    put("person", "second", [r.between(0.27, 0.31) * W, H - M - 34], 1.08, {
      pose: "mug",
    })
  else
    put("visitor", "second", [r.between(0.27, 0.31) * W, H - M - 34], 1.25, {
      pose: "record",
    })
  border()
  return s
}

function studio(seed: string, hand: HandName, take: number) {
  const { s, r, put, floor, walls, border } = stage(seed, hand, take)
  walls()
  put("window", "window", [r.between(0.24, 0.3) * W, floor - 120], 0.9)
  put("sticky-notes", "notes", [r.between(0.58, 0.62) * W, H * 0.3], 0.8)
  if (r.chance(0.6))
    put("picture", "picture", [r.between(0.84, 0.88) * W, H * 0.24], 0.65)
  const top = put("desk", "desk", [r.between(0.34, 0.4) * W, floor + 74], 1, {
    w: 280,
    d: 74,
    legs: 80,
  }) as Box
  put("books", "books", top.top(0.02, 0.62), 0.62)
  put("house-plant", "plant", top.top(0.32, 0.75), 0.65)
  if (r.chance(0.5)) put("monitor", "screen", top.top(0.62, 0.62), 1)
  else put("laptop", "screen", top.top(0.4, 0.3), 0.85)
  put("desk-lamp", "lamp", top.top(0.92, 0.7), 0.75)
  put("mug", "mug", top.top(0.2, 0.18), 0.62)
  put("person-mug", "person", [r.between(0.13, 0.18) * W, H - M - 22], 1.08)
  if (r.chance(0.6))
    put("cat", "cat", [r.between(0.82, 0.9) * W, H - M - 18], 0.9)
  border()
  return s
}

function bistro(seed: string, hand: HandName, take: number) {
  const { s, r, put, floor, walls, rug, border } = stage(seed, hand, take)
  walls()
  rug()
  put("picture", "picture", [r.between(0.72, 0.78) * W, H * 0.24], 0.8)
  put("window", "window", [r.between(0.28, 0.33) * W, floor - 128], 0.85, {
    view: "moon",
  })
  const x = r.between(0.5, 0.55) * W
  const y = H - M - 36
  put("pendant", "lamp", [x, H * 0.24], 1.05, { top: M })
  put("chair", "far", [x + 34, y - 22], 0.95)
  put("bistro-table", "table", [x, y], 1.1)
  const t: Point = [x, y - 114]
  put("bottle", "wine", [t[0] - 34, t[1] + 2], 0.62)
  put("candle", "candle", [t[0] + 44, t[1] - 2], 0.55)
  put("glass", "left", [t[0] - 12, t[1] + 8], 0.75)
  put("glass", "right", [t[0] + 22, t[1] + 4], 0.75)
  put("plate", "plate", [t[0] - 2, t[1] + 22], 0.62)
  put("person", "guest", [r.between(0.2, 0.25) * W, H - M - 20], 1.1, {
    pose: r.pick(["stand", "wave"]),
  })
  if (r.chance(0.5))
    put("visitor", "waiter", [r.between(0.84, 0.88) * W, H - M - 24], 1.1, {
      pose: "stand",
    })
  else put("cat", "cat", [r.between(0.84, 0.88) * W, H - M - 24], 0.9)
  border()
  return s
}

export interface Scene {
  name: string
  /** The accessible name of a drawing of this scene. */
  label: string
  size: [number, number]
  compose: (seed: string, hand: HandName, take: number) => Sheet
}

export const SCENES = {
  room: {
    name: "Listening room",
    label: "A room corner with a record shelf, a disco ball and visitors",
    size: [W, H],
    compose: room,
  },
  studio: {
    name: "Studio",
    label:
      "A studio with a desk, a screen, sticky notes and a person with a coffee",
    size: [W, H],
    compose: studio,
  },
  bistro: {
    name: "Bistro",
    label:
      "A bistro table for two with wine, a candle and a plate, under a pendant lamp",
    size: [W, H],
    compose: bistro,
  },
} satisfies Record<string, Scene>

export type SceneName = keyof typeof SCENES

// Shapes every object builds from: the oblique box, the upright cylinder, a cup's handle and lines of scribbled
// text. Objects take their own depth angle from the seed, so neighbours disagree a little about perspective.
import { add, arc, deg, lerp, type Point } from "./geometry"
import type { Stream } from "./seed"
import type { Sheet } from "./layers"
import type { Pen } from "./stroke"

/** Where "back" is for one object: up and to the right, at a seeded angle and depth. */
export function depth(r: Stream): Point {
  const a = (30 + r.signed() * 12) * deg
  const f = 0.5 + r.signed() * 0.1
  return [Math.cos(a) * f, -Math.sin(a) * f]
}

export interface Box {
  w: number
  d: number
  o: Point
  /** A point on the front face: u runs left to right, v bottom to top. */
  front(u: number, v: number): Point
  /** A point on the top face: u runs left to right, v front to back. */
  top(u: number, v: number): Point
}

/** An oblique box: front face w × h with its bottom-left corner at `at`, receding d along `o`. */
export function box(
  s: Sheet,
  p: Pen,
  o: Point,
  at: Point,
  w: number,
  h: number,
  d: number,
): Box {
  const [x, y] = at
  const A: Point = [x, y]
  const B: Point = [x + w, y]
  const C: Point = [x + w, y - h]
  const D: Point = [x, y - h]
  const back = (q: Point) => add(q, o, d)
  const [B2, C2, D2] = [back(B), back(C), back(D)]
  s.blank(p.shape([A, B, B2, C2, D2, D]))
  s.stroke(p.edges([A, B, C, D]))
  s.stroke(p.edges([D, D2, C2, C], false))
  s.stroke(p.edges([C2, B2, B], false))
  return {
    w,
    d,
    o,
    front: (u, v) => [x + w * u, y - h * v],
    top: (u, v) => add(lerp(D, C, u), o, d * v),
  }
}

/** An upright cylinder seen from a little above: `c` is the centre of its top. Returns its rims. */
export function cylinder(
  s: Sheet,
  p: Pen,
  c: Point,
  rx: number,
  ry: number,
  h: number,
) {
  const bottom: Point = [c[0], c[1] + h]
  s.blank(
    p.shape([
      ...arc(c, rx, ry, 180, 360, 12),
      ...arc(bottom, rx, ry, 0, 180, 12),
    ]),
  )
  s.stroke(p.ring(c, [rx, 0], [0, ry]))
  s.stroke(p.line([c[0] - rx, c[1]], [c[0] - rx, bottom[1]]))
  s.stroke(p.line([c[0] + rx, c[1]], [c[0] + rx, bottom[1]]))
  s.stroke(p.path(arc(bottom, rx, ry, 0, 180, 12)))
  return { top: c, bottom }
}

/** A handle on the side of a cup or jug, from y0 to y1 at x, bulging by `reach`. */
export function handle(
  s: Sheet,
  p: Pen,
  x: number,
  y0: number,
  y1: number,
  reach: number,
) {
  s.stroke(p.path(arc([x, (y0 + y1) / 2], reach, (y1 - y0) / 2, -90, 90, 10)))
}

/** Short wavy lines of text, for menus, notes and screens. */
export function scribble(
  s: Sheet,
  p: Pen,
  r: Stream,
  x: number,
  y: number,
  w: number,
  lines: number,
  gap = 7,
) {
  for (let i = 0; i < lines; i++) {
    const len =
      w * (i === lines - 1 ? r.between(0.35, 0.7) : r.between(0.75, 1))
    const pts = Array.from({ length: 6 }, (_, j): Point => [
      x + (len * j) / 5,
      y + i * gap + (j % 2 ? 0.8 : -0.8),
    ])
    s.stroke(p.path(pts))
  }
}

// The pen. Every line is one thin monoline stroke with a slow hand wobble, drawn from a seed, so the same seed always
// draws the same line. Ported from the prototype in specimen/pen.js, with Patina's cross-engine rules: inputs are
// snapped before they decide a count or a random draw, and no ** or Math.pow.
import { dist, last, length, snap, type Point } from "./geometry"
import { fork, prng, seedOf } from "./seed"

export type HandName = "calm" | "lively"

/**
 * How far a hand strays. amp: slow wobble in px; wave: its wavelength; tremor: fine shake; over: how far a line may
 * run past its end (a negative draw stops short); loop: the extra turn on a drawn circle, in radians.
 */
export const HANDS = {
  calm: { amp: 0.35, wave: 60, tremor: 0.08, over: 1.2, loop: 0.12 },
  lively: { amp: 1.1, wave: 40, tremor: 0.18, over: 4.5, loop: 0.45 },
} as const

const r1 = (n: number) => Math.round(n * 10) / 10

/** Slow 1D noise along a line: random offsets at knots `wave` apart, eased between them. */
export function noise(
  rand: () => number,
  size: number,
  wave: number,
  amp: number,
) {
  const n = Math.ceil(snap(size / wave)) + 2
  const knots = Array.from({ length: n }, () => (rand() * 2 - 1) * amp)
  return (s: number) => {
    const t = Math.max(0, s) / wave
    const i = Math.min(Math.floor(t), n - 2)
    const u = (1 - Math.cos((t - i) * Math.PI)) / 2
    return (knots[i] as number) * (1 - u) + (knots[i + 1] as number) * u
  }
}

export type Sample = [number, number, number]

/** Points every `step` px along a polyline, with their distance from the start. */
export function resample(points: Point[], step: number): Sample[] {
  const first = points[0] as Point
  const out: Sample[] = [[first[0], first[1], 0]]
  let s = 0
  for (let i = 1; i < points.length; i++) {
    const a = points[i - 1] as Point
    const b = points[i] as Point
    const len = snap(dist(a, b))
    const n = Math.max(1, Math.round(len / step))
    for (let j = 1; j <= n; j++) {
      const f = j / n
      out.push([
        a[0] + (b[0] - a[0]) * f,
        a[1] + (b[1] - a[1]) * f,
        s + len * f,
      ])
    }
    s += len
  }
  return out
}

function toPath(points: Point[], closed = false) {
  const d = points
    .map(([x, y], i) => `${i ? "L" : "M"}${r1(x)} ${r1(y)}`)
    .join("")
  return closed ? `${d}Z` : d
}

export interface Pen {
  hand: HandName
  /** The pen's own random stream, for choices an object makes while drawing. */
  next: () => number
  /** One straight stroke. */
  line(a: Point, b: Point): string
  /** A smooth open stroke through points. */
  path(points: Point[]): string
  /** A polygon drawn edge by edge, so its corners cross or fall short. */
  edges(points: Point[], closed?: boolean): string
  /** A closed outline in one stroke, for fills and blanks. */
  shape(points: Point[]): string
  /** A drawn ellipse (centre plus two axis vectors): the pen goes a little past where it started. */
  ring(c: Point, u: Point, v?: Point): string
  /** A closed ellipse outline, for solid discs. */
  disc(c: Point, u: Point, v?: Point): string
  /** Points round an ellipse from `from`, sweeping `turn` radians. */
  round(c: Point, u: Point, v: Point, from: number, turn: number): Point[]
}

/**
 * A pen with a hand. Each call draws the next stroke from the pen's own stream. Takes (line boil, settling) redraw
 * the same composition with another pen: a labelled fork per take, so take 0 is the drawing itself.
 */
export function pen(
  seed: string | number,
  handName: HandName = "lively",
  take = 0,
): Pen {
  const hand = HANDS[handName] ?? HANDS.lively
  const rand = prng(fork(seedOf(seed), take ? `pen:take:${take}` : "pen"))
  const between = (a: number, b: number) => a + rand() * (b - a)

  /** Offset a polyline along its normals by slow wobble plus tremor. `closed` makes the offsets meet. */
  function trace(points: Point[], closed = false): Point[] {
    const pts = resample(
      points.map(([x, y]) => [snap(x), snap(y)]),
      3,
    )
    const size = last(pts)[2] || 1
    const slow = noise(rand, size, hand.wave * between(0.8, 1.25), hand.amp)
    const fine = noise(rand, size, 7, hand.tremor)
    const start = slow(0) + fine(0)
    const end = slow(size) + fine(size)
    return pts.map(([x, y, s], i) => {
      const a = pts[Math.max(0, i - 1)] as Sample
      const b = pts[Math.min(pts.length - 1, i + 1)] as Sample
      const len = length([b[0] - a[0], b[1] - a[1]]) || 1
      let off = slow(s) + fine(s)
      if (closed) off -= ((end - start) * s) / size
      return [x - ((b[1] - a[1]) / len) * off, y + ((b[0] - a[0]) / len) * off]
    })
  }

  /** Run the first and last segment on past their ends (or stop short), as a quick hand does. */
  function overshoot(points: Point[]): Point[] {
    const pts = points.map((p) => [p[0], p[1]] as Point)
    const extend = (p: Point, q: Point) => {
      const len = dist(p, q) || 1
      const o = between(-0.25, 1) * hand.over
      p[0] += ((p[0] - q[0]) / len) * o
      p[1] += ((p[1] - q[1]) / len) * o
    }
    extend(pts[0] as Point, pts[1] as Point)
    extend(last(pts), pts[pts.length - 2] as Point)
    return pts
  }

  function round(c: Point, u: Point, v: Point, from: number, turn: number) {
    const span = snap(length(u) + length(v))
    const n = Math.max(12, Math.round(snap((span * turn) / 4)))
    return Array.from({ length: n + 1 }, (_, i): Point => {
      const t = from + (turn * i) / n
      return [
        c[0] + u[0] * Math.cos(t) + v[0] * Math.sin(t),
        c[1] + u[1] * Math.cos(t) + v[1] * Math.sin(t),
      ]
    })
  }

  return {
    hand: handName,
    next: rand,
    line: (a, b) => toPath(trace(overshoot([a, b]))),
    path: (points) => toPath(trace(overshoot(points))),
    edges(points, closed = true) {
      const ring = closed ? [...points, points[0] as Point] : points
      let d = ""
      for (let i = 1; i < ring.length; i++)
        d += toPath(trace(overshoot([ring[i - 1] as Point, ring[i] as Point])))
      return d
    },
    shape: (points) =>
      toPath(trace([...points, points[0] as Point], true), true),
    ring(c, u, v = [0, u[0]]) {
      const from = between(0, Math.PI * 2)
      const turn = Math.PI * 2 + between(0.3, 1) * hand.loop
      return toPath(trace(round(c, u, v, from, turn)))
    },
    disc(c, u, v = [0, u[0]]) {
      const pts = round(c, u, v, between(0, Math.PI * 2), Math.PI * 2)
      return toPath(trace([...pts.slice(0, -1), pts[0] as Point], true), true)
    },
    round,
  }
}
